function area(width, height) {
  return width * height;
}

console.log(area(3, 4));
console.log(area(2.5, 2));

const result = area(10, 10);
console.log(`The result is ${result}`);

function greet(name = "friend", punctuation = "!") {
  return `Hello, ${name}${punctuation}`;
}
console.log(greet());
console.log(greet("Ada"));
console.log(greet("Ada", "?"));

function logTwice(text) {
  console.log(text);
  console.log(text);
}
const nothing = logTwice("hi");
console.log(nothing);   // logTwice prints but does not return anything

const square = function (n) {
  return n * n;
};

const cube = (n) => n * n * n;           // single expression: implicit return
const add = (a, b) => a + b;
const describe = (n) => {                 // several statements need braces and return
  const kind = n % 2 === 0 ? "even" : "odd";
  return `${n} is ${kind}`;
};

console.log(square(4));
console.log(cube(2));
console.log(add(2, 3));
console.log(describe(7));

function makeCounter() {
  let count = 0;            // private to this counter
  return function () {
    count++;
    return count;
  };
}

const counterA = makeCounter();
const counterB = makeCounter();   // a separate count
console.log(counterA());
console.log(counterA());
console.log(counterB());

function repeat(times, action) {
  for (let i = 1; i <= times; i++) {
    action(i);
  }
}

repeat(3, (n) => console.log(`Tick ${n}`));

function applyDiscount(price) {
  return price * 0.9;
}
const prices = [10, 20];
console.log(prices.map(applyDiscount).join(", "));

console.log(double(4));        // works: declarations are hoisted

function double(n) {
  return n * 2;
}

try {
  console.log(triple(4));      // fails: the const is not initialised yet
} catch (error) {
  console.log(error.name);
}
const triple = (n) => n * 3;
